const body = $input.item.json.body || {};
const required = ['nombre', 'apellido', 'matricula_tipo', 'matricula_numero', 'email', 'firma_url'];
const faltantes = required.filter((campo) => !body[campo] || String(body[campo]).trim() === '');

if (faltantes.length > 0) {
  throw new Error(`Faltan campos obligatorios: ${faltantes.join(', ')}`);
}

const matricula_tipo = String(body.matricula_tipo).trim().toUpperCase();
const matricula_numero = String(body.matricula_numero).trim();
const matricula_2_tipo = body.matricula_2_tipo ? String(body.matricula_2_tipo).trim().toUpperCase() : null;
const matricula_2_numero = body.matricula_2_numero ? String(body.matricula_2_numero).trim() : null;

if (!['MN', 'MP'].includes(matricula_tipo)) {
  throw new Error('matricula_tipo debe ser MN o MP');
}
if (!/^[0-9]+$/.test(matricula_numero)) {
  throw new Error('matricula_numero debe contener solo dígitos');
}
if ((matricula_2_tipo === null) !== (matricula_2_numero === null)) {
  throw new Error('Matrícula 2 incompleta: hacen falta matricula_2_tipo y matricula_2_numero, o ninguno');
}
if (matricula_2_tipo !== null) {
  if (!['MN', 'MP'].includes(matricula_2_tipo)) {
    throw new Error('matricula_2_tipo debe ser MN o MP');
  }
  if (!/^[0-9]+$/.test(matricula_2_numero)) {
    throw new Error('matricula_2_numero debe contener solo dígitos');
  }
}

return {
  json: {
    nombre: String(body.nombre).trim(),
    apellido: String(body.apellido).trim(),
    matricula_tipo,
    matricula_numero,
    matricula_2_tipo,
    matricula_2_numero,
    email: String(body.email).trim().toLowerCase(),
    especialidad: body.especialidad ? String(body.especialidad).trim() : null,
    firma_url: String(body.firma_url).trim(),
    activo: true
  }
};

